cd /filesystem && cat > /tmp/dumpxl.py << 'EOF'
import openpyxl, sys
from openpyxl.utils import get_column_letter
path = sys.argv[1]
wb = openpyxl.load_workbook(path, data_only=False)
wbv = openpyxl.load_workbook(path, data_only=True)
for ws in wb.worksheets:
    wsv = wbv[ws.title]
    print(f"===== SHEET: {ws.title}  dims={ws.dimensions} state={ws.sheet_state}")
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None:
                v = wsv[c.coordinate].value
                if isinstance(c.value, str) and c.value.startswith('='):
                    print(f"{c.coordinate}: {c.value!r}  -> {v!r}")
                else:
                    print(f"{c.coordinate}: {c.value!r}")
    # merged cells, comments
    if ws.merged_cells.ranges:
        print("MERGED:", [str(r) for r in ws.merged_cells.ranges][:50])
    for row in ws.iter_rows():
        for c in row:
            if c.comment:
                print(f"COMMENT {c.coordinate}: {c.comment.text!r}")
# defined names
try:
    for n in wb.defined_names:
        print("NAME:", n, wb.defined_names[n].attr_text)
except Exception as e:
    try:
        for n in wb.defined_names.definedName:
            print("NAME:", n.name, n.attr_text)
    except Exception as e2:
        print("names err", e2)
EOF
