cd /filesystem && rm -rf /tmp/txt && mkdir -p /tmp/txt && python3 - << 'EOF'
import os, subprocess
for root, dirs, files in os.walk('.'):
    for fn in files:
        p = os.path.join(root, fn)
        out = '/tmp/txt/' + p[2:].replace('/', '__') + '.txt'
        ext = fn.lower().rsplit('.',1)[-1]
        try:
            if ext == 'pdf':
                subprocess.run(['pdftotext','-layout',p,out],check=True)
            elif ext == 'docx':
                subprocess.run(['pandoc',p,'-t','plain','--wrap=none','-o',out],check=True)
            elif ext == 'xlsx':
                with open(out,'w') as f:
                    subprocess.run(['python3','/tmp/dumpxl.py',p],stdout=f,check=True)
            elif ext == 'eml':
                subprocess.run(['cp',p,out],check=True)
        except Exception as e:
            print("ERR", p, e)
print(len(os.listdir('/tmp/txt')))
